/* Thinkers Foundation - the deck, generated from the guide */
window.THINKERS = [{"n": "Protagoras", "d": "c. 490–420 BCE", "w": "Fragments; portrayed in Plato’s Protagoras", "s": "“Man is the measure of all things”: justice and law are human conventions, teachable as civic skill, an early democratic and relativist wager rolled into one.", "g": "thinker-protagoras", "k": "Protagoras", "c": "The Sophists", "e": "Ancient Political Thought"}, {"n": "Thrasymachus", "d": "fl. late 5th century BCE", "w": "Appears in Book I of Plato’s Republic", "s": "Defined justice as the advantage of the stronger: rulers make laws in their own interest and call obedience “just.” The classic statement of political realism that the Republic is written to refute.", "g": "thinker-thrasymachus", "k": "Thrasymachus", "c": "The Sophists", "e": "Ancient Political Thought"}, {"n": "Socrates", "d": "470–399 BCE", "w": "Wrote nothing; known through Plato’s Apology and Crito and through Xenophon", "s": "Made the examined life the precondition of citizenship. His trial and execution by democratic Athens pose the founding problem of the tradition: what does the individual conscience owe the city, and the city the philosopher?", "g": "thinker-socrates", "k": "Socrates", "c": "The Classical Greeks (Socratic tradition)", "e": "Ancient Political Thought"}, {"n": "Plato", "d": "c. 428–348 BCE", "w": "Republic; Statesman; Laws", "s": "Justice in the soul mirrors justice in the city; the best regime is rule by philosopher-kings who know the Good, with the famous critique of democracy as rule by appetite. The late Laws offers a sober second-best: mixed government under the sovereignty of law.", "g": "thinker-plato", "k": "Plato", "c": "The Classical Greeks (Socratic tradition)", "e": "Ancient Political Thought"}, {"n": "Aristotle", "d": "384–322 BCE", "w": "Politics; Nicomachean Ethics; Constitution of the Athenians", "s": "Man is by nature a political animal; the polis exists for the good life, not mere life. Classified regimes by who rules and for whose benefit, defended the middle class and the mixed constitution, and founded empirical comparative politics by studying 158 constitutions.", "g": "thinker-aristotle", "k": "Aristotle", "c": "The Classical Greeks (Socratic tradition)", "e": "Ancient Political Thought"}, {"n": "Diogenes of Sinope", "d": "c. 412–323 BCE", "w": "No surviving works; anecdotes via Diogenes Laërtius", "s": "Rejected wealth, status, and civic convention in favor of radical self-sufficiency; when asked where he was from, answered “a citizen of the world”, coining cosmopolitanism and dissolving loyalty to any particular polis.", "g": "thinker-diogenes-of-sinope", "k": "Diogenes", "c": "Cynicism", "e": "Ancient Political Thought"}, {"n": "Epicurus", "d": "341–270 BCE", "w": "Principal Doctrines; Letter to Menoeceus", "s": "Justice is a contract neither to harm nor be harmed: an early social-contract intuition. There is no justice in itself, only agreements that track mutual advantage; the prudent person avoids public life (“live unnoticed”).", "g": "thinker-epicurus", "k": "Epicurus", "c": "Epicureanism", "e": "Ancient Political Thought"}, {"n": "Lucretius", "d": "c. 99–55 BCE", "w": "De Rerum Natura (On the Nature of Things)", "s": "Versified Epicurean naturalism, including a conjectural history in which language, law, and kingship arise from convenience and fear rather than divine design: a template for later state-of-nature stories.", "g": "thinker-lucretius", "k": "Lucretius", "c": "Epicureanism", "e": "Ancient Political Thought"}, {"n": "Zeno of Citium", "d": "c. 334–262 BCE", "w": "Republic (lost)", "s": "Founded Stoicism and imagined a cosmopolis of the wise governed by reason rather than local statutes: the school’s scandalous founding utopia.", "g": "thinker-zeno-of-citium", "k": "Zeno of Citium", "c": "Stoicism", "e": "Ancient Political Thought"}, {"n": "Cicero", "d": "106–43 BCE", "w": "De Re Publica; De Legibus; De Officiis", "s": "Transmitted Greek philosophy to Rome and to every later century. Defined natural law as right reason in agreement with nature, universal, unchanging, above the statutes of any city, and defended the mixed constitution of the Roman republic as the most stable regime.", "g": "thinker-cicero", "k": "Cicero", "c": "Stoicism", "e": "Ancient Political Thought"}, {"n": "Seneca", "d": "c. 4 BCE–65 CE", "w": "De Clementia; Letters to Lucilius", "s": "Stoic adviser to Nero: on mercy as the distinctive virtue of rulers, and on how inner freedom survives under tyranny, a manual for philosophy in dark times.", "g": "thinker-seneca", "k": "Seneca the Younger", "c": "Stoicism", "e": "Ancient Political Thought"}, {"n": "Epictetus", "d": "c. 50–135 CE", "w": "Discourses; Enchiridion", "s": "A former slave who taught that freedom is mastery of what is “up to us”: no external power can compel the will. The most radical ancient statement of inner liberty.", "g": "thinker-epictetus", "k": "Epictetus", "c": "Stoicism", "e": "Ancient Political Thought"}, {"n": "Marcus Aurelius", "d": "121–180 CE", "w": "Meditations", "s": "The philosopher-emperor’s private notebook of Stoic self-government: duty, cosmopolitan reason, and the discipline of judgment, political power examined from the inside.", "g": "thinker-marcus-aurelius", "k": "Marcus Aurelius", "c": "Stoicism", "e": "Ancient Political Thought"}, {"n": "Polybius", "d": "c. 200–118 BCE", "w": "Histories (Book VI)", "s": "Theorized the cycle of regimes (anacyclosis), kingship decays to tyranny, aristocracy to oligarchy, democracy to mob rule, and explained Rome’s stability by its mixed constitution balancing consuls, senate, and people: the ancestor of separation-of-powers thinking.", "g": "thinker-polybius", "k": "Polybius", "c": "Roman Constitutionalism", "e": "Ancient Political Thought"}, {"n": "Confucius", "d": "551–479 BCE", "w": "Analects", "s": "Government by virtue and ritual propriety rather than punishment: the ruler is a moral exemplar, and social harmony flows from rectified relationships and names. Law compels; virtue transforms.", "g": "thinker-confucius", "k": "Confucius", "c": "Ancient Indian and Chinese Statecraft", "e": "Ancient Political Thought"}, {"n": "Mencius", "d": "372–289 BCE", "w": "Mencius", "s": "Human nature is good, and rulers hold a revocable Mandate of Heaven: a king who preys on his people forfeits the title, and the people may justly depose him, the Confucian right of rebellion.", "g": "thinker-mencius", "k": "Mencius", "c": "Ancient Indian and Chinese Statecraft", "e": "Ancient Political Thought"}, {"n": "Han Feizi", "d": "c. 280–233 BCE", "w": "Han Feizi", "s": "Legalism: order rests on clear public law, strict punishment, and institutional design (fa, shu, shi), not on the ruler’s virtue, an ancient theory of incentives that assumes officials and subjects alike respond to reward and fear.", "g": "thinker-han-feizi", "k": "Han Fei", "c": "Ancient Indian and Chinese Statecraft", "e": "Ancient Political Thought"}, {"n": "Kautilya (Chanakya)", "d": "trad. c. 4th century BCE", "w": "Arthashastra", "s": "The encyclopedic Indian treatise on statecraft: taxation, espionage, diplomacy (the mandala theory of encircling states), and war, joined to the king’s welfare duty (yogakshema). Its unsentimental realism invites the standing comparison with Machiavelli: written some eighteen centuries earlier.", "g": "thinker-kautilya-chanakya", "k": "Chanakya", "c": "Ancient Indian and Chinese Statecraft", "e": "Ancient Political Thought"}, {"n": "Niccolò Machiavelli", "d": "1469–1527", "w": "The Prince; Discourses on Livy", "s": "Severed politics from moral idealism: the prince must learn how not to be good, managing fortuna with virtù, because a ruler who is always good will be ruined among so many who are not. The Discourses show the other Machiavelli: republican liberty, civic religion, and productive class conflict as the source of good laws.", "g": "thinker-niccolo-machiavelli", "k": "Niccolò Machiavelli", "c": "Civic Humanism and Political Realism", "e": "Renaissance and Early Modern Thought"}, {"n": "Thomas More", "d": "1478–1535", "w": "Utopia", "s": "Coined the genre: a satirical portrait of a communal island commonwealth without private property or money, holding a mirror to European avarice, enclosure, and penal cruelty, and leaving deliberately ambiguous whether it is blueprint or jest.", "g": "thinker-thomas-more", "k": "Thomas More", "c": "Utopianism", "e": "Renaissance and Early Modern Thought"}, {"n": "Jean Bodin", "d": "1530–1596", "w": "Six Books of the Commonwealth", "s": "Defined sovereignty as the absolute and perpetual power to make law: indivisible, above positive law, answerable only to divine and natural law. Forged amid France’s religious wars, it is the conceptual foundation of the modern state that Hobbes would radicalize.", "g": "thinker-jean-bodin", "k": "Jean Bodin", "c": "Sovereignty Theory", "e": "Renaissance and Early Modern Thought"}, {"n": "Francisco de Vitoria", "d": "c. 1483–1546", "w": "De Indis; De Jure Belli", "s": "Argued the peoples of the Americas held genuine dominion, rights that conquest could not simply erase, and laid foundations of international law and just-war doctrine against imperial pretension.", "g": "thinker-francisco-de-vitoria", "k": "Francisco de Vitoria", "c": "The School of Salamanca", "e": "Renaissance and Early Modern Thought"}, {"n": "Francisco Suárez", "d": "1548–1617", "w": "De Legibus", "s": "Late-scholastic system of law and the state: political power derives from the community and is transferred, not surrendered, to rulers, a bridge from Aquinas to social-contract constitutionalism.", "g": "thinker-francisco-suarez", "k": "Francisco Suárez", "c": "The School of Salamanca", "e": "Renaissance and Early Modern Thought"}, {"n": "Hugo Grotius", "d": "1583–1645", "w": "De Jure Belli ac Pacis; Mare Liberum", "s": "The father of modern international law: natural law would hold “even if God did not exist,” because it flows from human sociability, grounding rights, property, contract, and the laws of war in a secular foundation, and defending the freedom of the seas.", "g": "thinker-hugo-grotius", "k": "Hugo Grotius", "c": "Natural Law and the Law of Nations", "e": "Renaissance and Early Modern Thought"}, {"n": "René Descartes", "d": "1596–1650", "w": "Discourse on the Method; Meditations on First Philosophy", "s": "Not a political writer, but the founder of the method: radical doubt, the cogito, and the ambition to rebuild all knowledge from indubitable foundations. Hobbes and Spinoza applied precisely this geometric template to politics.", "g": "thinker-rene-descartes", "k": "René Descartes", "c": "The Rationalists", "e": "The Age of Reason and the Enlightenment"}, {"n": "Baruch Spinoza", "d": "1632–1677", "w": "Theological-Political Treatise; Political Treatise; Ethics", "s": "Applied the geometric method to God, man, and state. Defended freedom of thought and speech as the very purpose of the commonwealth, “the true aim of government is liberty”, judged democracy the most natural regime, and pioneered biblical criticism to disarm theocratic politics.", "g": "thinker-baruch-spinoza", "k": "Baruch Spinoza", "c": "The Rationalists", "e": "The Age of Reason and the Enlightenment"}, {"n": "Gottfried Wilhelm Leibniz", "d": "1646–1716", "w": "Theodicy; Monadology", "s": "Systematic rationalist of pre-established harmony; in jurisprudence sought a universal science of right and defined justice as the charity of the wise, benevolence disciplined by reason.", "g": "thinker-gottfried-wilhelm-leibniz", "k": "Gottfried Wilhelm Leibniz", "c": "The Rationalists", "e": "The Age of Reason and the Enlightenment"}, {"n": "John Locke (epistemology)", "d": "1632–1704", "w": "An Essay Concerning Human Understanding", "s": "The mind as white paper, furnished by sensation and reflection: an epistemology of experience that matches his politics of consent, no innate ideas, and no innate rulers. (For his political theory, see Social Contract below.)", "g": "thinker-john-locke-epistemology", "k": "John Locke", "c": "The Empiricists", "e": "The Age of Reason and the Enlightenment"}, {"n": "George Berkeley", "d": "1685–1753", "w": "A Treatise Concerning the Principles of Human Knowledge", "s": "Idealist empiricism (esse est percipi); politically minor, but sharpened the empiricist critique of abstraction that Hume would turn on political fictions.", "g": "thinker-george-berkeley", "k": "George Berkeley", "c": "The Empiricists", "e": "The Age of Reason and the Enlightenment"}, {"n": "David Hume", "d": "1711–1776", "w": "A Treatise of Human Nature; Essays, Moral, Political, and Literary; History of England", "s": "Demolished the fiction of an original contract: government everywhere rests on opinion, habit, and utility. Justice and property are “artificial virtues”, conventions that evolve because they serve everyone, making Hume the great forerunner of spontaneous-order thinking and of skeptical, gradualist liberalism.", "g": "thinker-david-hume", "k": "David Hume", "c": "The Empiricists", "e": "The Age of Reason and the Enlightenment"}, {"n": "Thomas Hobbes", "d": "1588–1679", "w": "Leviathan; De Cive", "s": "In the state of nature, a war of all against all, life is “solitary, poor, nasty, brutish, and short.” Rational fear drives men to covenant, authorizing an absolute sovereign whose one job is peace. Materialist, geometry-inspired, and the true beginning of modern political science: order without God’s sanction, built from individual motives up.", "g": "thinker-thomas-hobbes", "k": "Thomas Hobbes", "c": "Social Contract Theory", "e": "The Age of Reason and the Enlightenment"}, {"n": "John Locke (politics)", "d": "1632–1704", "w": "Two Treatises of Government; A Letter Concerning Toleration", "s": "Natural rights to life, liberty, and property precede government; political power is a fiduciary trust, limited by its ends and revocable, the people may resist a tyrant. Property arises from mixing labor with nature. The charter of liberal constitutionalism and, with the Letter, of religious toleration.", "g": "thinker-john-locke-politics", "k": "John Locke", "c": "Social Contract Theory", "e": "The Age of Reason and the Enlightenment"}, {"n": "Jean-Jacques Rousseau", "d": "1712–1778", "w": "Discourse on Inequality; The Social Contract; Émile", "s": "“Man is born free, and everywhere he is in chains”: inequality is conventional, not natural, and legitimacy requires the general will, under which each obeys only himself. Inspired democratic republicanism and civic religion: and, critics from Constant to Berlin argue, the totalitarian temptation of forcing men to be free.", "g": "thinker-jean-jacques-rousseau", "k": "Jean-Jacques Rousseau", "c": "Social Contract Theory", "e": "The Age of Reason and the Enlightenment"}, {"n": "Montesquieu", "d": "1689–1755", "w": "The Spirit of the Laws; Persian Letters", "s": "Laws must fit a nation’s climate, commerce, and customs, the general spirit, and liberty survives only where power checks power. His separation of legislative, executive, and judicial powers became the operating system of the American Constitution.", "g": "thinker-montesquieu", "k": "Montesquieu", "c": "The French Enlightenment (les philosophes)", "e": "The Age of Reason and the Enlightenment"}, {"n": "Voltaire", "d": "1694–1778", "w": "Philosophical Letters; Treatise on Toleration; Candide", "s": "The century’s scourge of fanaticism and censorship (écrasez l’infâme): made religious toleration and freedom of the pen the common cause of enlightened Europe, wielding wit as a political weapon.", "g": "thinker-voltaire", "k": "Voltaire", "c": "The French Enlightenment (les philosophes)", "e": "The Age of Reason and the Enlightenment"}, {"n": "Denis Diderot", "d": "1713–1784", "w": "Encyclopédie (ed.); Supplement to the Voyage of Bougainville", "s": "General editor of the Enlightenment’s greatest engine of diffusion; critic of despotism, empire, and clerical authority, smuggling subversion through cross-references.", "g": "thinker-denis-diderot", "k": "Denis Diderot", "c": "The French Enlightenment (les philosophes)", "e": "The Age of Reason and the Enlightenment"}, {"n": "Marquis de Condorcet", "d": "1743–1794", "w": "Sketch for a Historical Picture of the Progress of the Human Mind; Essay on the Application of Analysis to the Probability of Majority Decisions", "s": "Prophet of indefinite progress and pioneer of social mathematics: the jury theorem and the voting paradox that founded social choice theory. Feminist and abolitionist; wrote the Sketch while hiding from the Terror that killed him.", "g": "thinker-marquis-de-condorcet", "k": "Nicolas de Condorcet", "c": "The French Enlightenment (les philosophes)", "e": "The Age of Reason and the Enlightenment"}, {"n": "Adam Smith", "d": "1723–1790", "w": "The Theory of Moral Sentiments; The Wealth of Nations", "s": "Sympathy and the impartial spectator ground morals; the division of labor and the invisible hand show how self-interested exchange, within a framework of justice, yields unintended public benefit. The founding charter of political economy: and a subtler moral psychology than the caricature suggests.", "g": "thinker-adam-smith", "k": "Adam Smith", "c": "The Scottish Enlightenment", "e": "The Age of Reason and the Enlightenment"}, {"n": "Adam Ferguson", "d": "1723–1816", "w": "An Essay on the History of Civil Society", "s": "Civil society’s institutions are “the result of human action, but not the execution of any human design”: the canonical statement of spontaneous order. Warned that commercial refinement can corrode the civic virtue on which free states depend.", "g": "thinker-adam-ferguson", "k": "Adam Ferguson", "c": "The Scottish Enlightenment", "e": "The Age of Reason and the Enlightenment"}, {"n": "Thomas Paine", "d": "1737–1809", "w": "Common Sense; Rights of Man; The Age of Reason", "s": "The revolution’s pamphleteer: society is a blessing, government at best a necessary evil; hereditary rule is an absurdity; and each generation must be free to remake its institutions, the most radical democratic voice of the age.", "g": "thinker-thomas-paine", "k": "Thomas Paine", "c": "The American Founding", "e": "The Age of Reason and the Enlightenment"}, {"n": "Madison, Hamilton, and Jay", "d": "published 1787–88", "w": "The Federalist Papers", "s": "The classic defense of the U.S. Constitution: an extended republic tames faction by multiplying interests (No. 10), and liberty is preserved when “ambition… counteract[s] ambition” through separated, mutually checking powers (No. 51): constitutional design for men who are not angels.", "g": "thinker-madison-hamilton-and-jay", "k": "James Madison", "c": "The American Founding", "e": "The Age of Reason and the Enlightenment"}, {"n": "Mary Wollstonecraft", "d": "1759–1797", "w": "A Vindication of the Rights of Woman; A Vindication of the Rights of Men", "s": "Extended Enlightenment rights to women: the mind has no sex, apparent female frivolity is manufactured by mis-education, and civic virtue requires independent, rationally educated female citizens. The founding text of liberal feminism.", "g": "thinker-mary-wollstonecraft", "k": "Mary Wollstonecraft", "c": "Enlightenment Feminism", "e": "The Age of Reason and the Enlightenment"}, {"n": "Immanuel Kant", "d": "1724–1804", "w": "Critique of Pure Reason; Groundwork of the Metaphysics of Morals; Perpetual Peace; The Metaphysics of Morals", "s": "United reason and experience in the critical philosophy; grounded morality in autonomy under the categorical imperative, persons as ends, never merely means. Politics is the framework of equal external freedom under universal law; republican constitutions, a federation of free states, and cosmopolitan hospitality mark the road to perpetual peace.", "g": "thinker-immanuel-kant", "k": "Immanuel Kant", "c": "The Kantian Synthesis", "e": "The Age of Reason and the Enlightenment"}, {"n": "Johann Gottlieb Fichte", "d": "1762–1814", "w": "Foundations of Natural Right; Addresses to the German Nation", "s": "Right is the condition under which free self-conscious beings can coexist: mutual recognition before Hegel made it famous. Later a prophet of national education and the closed commercial state, an early theorist of economic nationalism.", "g": "thinker-johann-gottlieb-fichte", "k": "Johann Gottlieb Fichte", "c": "German Idealism", "e": "The Nineteenth Century"}, {"n": "G. W. F. Hegel", "d": "1770–1831", "w": "Elements of the Philosophy of Right; Phenomenology of Spirit", "s": "Freedom is realized, not merely possessed: through family, civil society, and the rational constitutional state, “what is rational is actual.” The master–slave dialectic and the analysis of civil society, the market sphere with its wealth and rabble, shaped Marxism, communitarianism, and recognition theory alike.", "g": "thinker-g-w-f-hegel", "k": "Georg Wilhelm Friedrich Hegel", "c": "German Idealism", "e": "The Nineteenth Century"}, {"n": "Edmund Burke", "d": "1729–1797", "w": "Reflections on the Revolution in France", "s": "Society is a partnership between the living, the dead, and the yet unborn; rights are a concrete inheritance, not abstract metaphysics; and revolutions that raze inherited institutions end in military despotism, a prediction the Terror and Napoleon obligingly confirmed. The founding text of modern conservatism.", "g": "thinker-edmund-burke", "k": "Edmund Burke", "c": "Conservatism", "e": "The Nineteenth Century"}, {"n": "Joseph de Maistre", "d": "1753–1821", "w": "Considerations on France; St Petersburg Dialogues", "s": "Theocratic counter-revolutionary: constitutions cannot be written, only grown; man is too corrupt for self-rule, and authority, throne, altar, and executioner, is what holds society together. The dark extreme of the reaction.", "g": "thinker-joseph-de-maistre", "k": "Joseph de Maistre", "c": "Conservatism", "e": "The Nineteenth Century"}, {"n": "Benjamin Constant", "d": "1767–1830", "w": "The Liberty of the Ancients Compared with That of the Moderns; Principles of Politics", "s": "Ancient liberty, collective self-rule, must not devour modern liberty, private independence under law. Representative government exists to protect the latter; Rousseau’s error was importing the first into a world built for the second.", "g": "thinker-benjamin-constant", "k": "Benjamin Constant", "c": "Classical Liberalism", "e": "The Nineteenth Century"}, {"n": "Alexis de Tocqueville", "d": "1805–1859", "w": "Democracy in America; The Old Regime and the Revolution", "s": "Equality of conditions is providential and irreversible; its dangers, tyranny of the majority, mild “soft despotism,” individual isolation, are met by associations, local self-government, religion, and mores. The most discerning of democracy’s friends, and the most exacting.", "g": "thinker-alexis-de-tocqueville", "k": "Alexis de Tocqueville", "c": "Classical Liberalism", "e": "The Nineteenth Century"}, {"n": "Herbert Spencer", "d": "1820–1903", "w": "Social Statics; The Man Versus the State", "s": "The law of equal freedom, each may do as he wills, provided he infringes not the equal freedom of any other, joined to evolutionary sociology and a fierce late-century polemic against creeping state paternalism, “the coming slavery.”", "g": "thinker-herbert-spencer", "k": "Herbert Spencer", "c": "Classical Liberalism", "e": "The Nineteenth Century"}, {"n": "Jeremy Bentham", "d": "1748–1832", "w": "An Introduction to the Principles of Morals and Legislation; A Fragment on Government", "s": "Pleasure and pain are the sovereign masters; the felicific calculus makes legislation a science; natural rights are “nonsense upon stilts.” Law, punishment, and institutions (the Panopticon included) become instruments of deliberate social engineering.", "g": "thinker-jeremy-bentham", "k": "Jeremy Bentham", "c": "Utilitarianism", "e": "The Nineteenth Century"}, {"n": "John Stuart Mill", "d": "1806–1873", "w": "On Liberty; Utilitarianism; Considerations on Representative Government; The Subjection of Women; Principles of Political Economy", "s": "The harm principle guards individuality against both state coercion and the “despotism of custom”; higher pleasures and the cultivation of character reform Bentham from within; representative government is a school for citizens; and the legal subordination of women is wrong in itself, a relic of the law of force. Liberalism’s central text and its conscience.", "g": "thinker-john-stuart-mill", "k": "John Stuart Mill", "c": "Utilitarianism", "e": "The Nineteenth Century"}, {"n": "Henry Sidgwick", "d": "1838–1900", "w": "The Methods of Ethics", "s": "The most rigorous classical statement of utilitarianism: and the most honest, ending in the unresolved “dualism of practical reason” between impartial duty and rational self-interest.", "g": "thinker-henry-sidgwick", "k": "Henry Sidgwick", "c": "Utilitarianism", "e": "The Nineteenth Century"}, {"n": "Saint-Simon, Fourier, and Owen", "d": "1760–1858", "w": "Saint-Simon, The Industrial System; Fourier, The Theory of the Four Movements; Owen, A New View of Society", "s": "The “utopian socialists”: administration of things by industrial experts, cooperative phalansteries harmonizing the passions, and model factory communities, three pre-Marxian answers to industrial misery, remembered chiefly through Marx and Engels’s affectionate demolition.", "g": "thinker-saint-simon-fourier-and-owen", "k": "Henri de Saint-Simon", "c": "Socialism and Marxism", "e": "The Nineteenth Century"}, {"n": "Karl Marx", "d": "1818–1883", "w": "The Communist Manifesto (with Engels); Capital; The German Ideology; Economic and Philosophic Manuscripts of 1844", "s": "Historical materialism: the mode of production shapes law, politics, and consciousness, and history advances through class struggle. Capitalism, driven by surplus-value extraction and prone to crisis, creates its own gravedigger in the proletariat. Alienation, ideology, and exploitation remain the core vocabulary of radical critique.", "g": "thinker-karl-marx", "k": "Karl Marx", "c": "Socialism and Marxism", "e": "The Nineteenth Century"}, {"n": "Friedrich Engels", "d": "1820–1895", "w": "The Condition of the Working Class in England; Anti-Dühring; The Origin of the Family, Private Property and the State", "s": "Marx’s collaborator, funder, and systematizer: documented industrial immiseration firsthand, codified “scientific socialism,” and tied the family and the state to the history of property forms.", "g": "thinker-friedrich-engels", "k": "Friedrich Engels", "c": "Socialism and Marxism", "e": "The Nineteenth Century"}, {"n": "Pierre-Joseph Proudhon", "d": "1809–1865", "w": "What Is Property?; The Federative Principle", "s": "“Property is theft”, yet property is also liberty: mutualism seeks order through free contract, credit, and federation, without the state. The first man to call himself an anarchist.", "g": "thinker-pierre-joseph-proudhon", "k": "Pierre-Joseph Proudhon", "c": "Anarchism", "e": "The Nineteenth Century"}, {"n": "Mikhail Bakunin", "d": "1814–1876", "w": "God and the State; Statism and Anarchy", "s": "Collectivist anarchist and Marx’s great rival in the First International; his prophecy that the “dictatorship of the proletariat” would become a dictatorship over the proletariat acquired sombre vindication after 1917.", "g": "thinker-mikhail-bakunin", "k": "Mikhail Bakunin", "c": "Anarchism", "e": "The Nineteenth Century"}, {"n": "Peter Kropotkin", "d": "1842–1921", "w": "Mutual Aid; The Conquest of Bread", "s": "Cooperation, not only competition, drives evolution, a naturalist’s rebuttal to social Darwinism, grounding an anarchist communism of free, federated communes.", "g": "thinker-peter-kropotkin", "k": "Peter Kropotkin", "c": "Anarchism", "e": "The Nineteenth Century"}, {"n": "Max Stirner", "d": "1806–1856", "w": "The Ego and Its Own", "s": "Radical egoism dissolving all “spooks”, state, humanity, morality, even “Man”, before the unique individual; the anarchism of one.", "g": "thinker-max-stirner", "k": "Max Stirner", "c": "Anarchism", "e": "The Nineteenth Century"}, {"n": "Henry David Thoreau", "d": "1817–1862", "w": "Civil Disobedience; Walden", "s": "The individual conscience outranks the state: a citizen’s duty is to withdraw support from injustice, prison being “the true place for a just man” under an unjust government. Direct inspiration for Gandhi and Martin Luther King Jr.", "g": "thinker-henry-david-thoreau", "k": "Henry David Thoreau", "c": "Radical Individualism and the Revaluation of Values", "e": "The Nineteenth Century"}, {"n": "Friedrich Nietzsche", "d": "1844–1900", "w": "On the Genealogy of Morality; Beyond Good and Evil; Thus Spoke Zarathustra", "s": "Genealogy unmasks morality as the product of ressentiment, slave revolt in values; the “death of God” opens the crisis of nihilism; will to power and the revaluation of all values answer it. An anti-political thinker whose shadow lies across the entire twentieth century.", "g": "thinker-friedrich-nietzsche", "k": "Friedrich Nietzsche", "c": "Radical Individualism and the Revaluation of Values", "e": "The Nineteenth Century"}, {"n": "Max Weber", "d": "1864–1920", "w": "Politics as a Vocation; Economy and Society; The Protestant Ethic and the Spirit of Capitalism", "s": "The state is the human community claiming a monopoly on legitimate violence within a territory; authority is traditional, charismatic, or legal-rational; modernity is disenchantment and the “iron cage” of bureaucracy. The politician needs an ethic of responsibility, not merely of conviction.", "g": "thinker-max-weber", "k": "Max Weber", "c": "Political Sociology and Democratic Realism", "e": "The Twentieth Century"}, {"n": "Robert Michels", "d": "1876–1936", "w": "Political Parties", "s": "The iron law of oligarchy: who says organization says oligarchy, even socialist parties devoted to equality develop entrenched ruling elites. The most discomfiting theorem in organisational sociology.", "g": "thinker-robert-michels", "k": "Robert Michels", "c": "Political Sociology and Democratic Realism", "e": "The Twentieth Century"}, {"n": "Joseph Schumpeter", "d": "1883–1950", "w": "Capitalism, Socialism and Democracy", "s": "Democracy redefined as competitive struggle among elites for the people’s vote, a method, not an ideal of popular self-rule; capitalism’s “creative destruction” drives progress even as its cultural success breeds the intellectuals who undermine it.", "g": "thinker-joseph-schumpeter", "k": "Joseph Schumpeter", "c": "Political Sociology and Democratic Realism", "e": "The Twentieth Century"}, {"n": "John Dewey", "d": "1859–1952", "w": "The Public and Its Problems; Democracy and Education", "s": "Democracy is more than machinery: it is a mode of associated living, sustained by education, communication, and experimental social intelligence. Publics form around the indirect consequences of action: and the problem of modern politics is that the public is “in eclipse.”", "g": "thinker-john-dewey", "k": "John Dewey", "c": "American Pragmatism", "e": "The Twentieth Century"}, {"n": "Ludwig von Mises", "d": "1881–1973", "w": "Socialism; Human Action; Liberalism", "s": "The socialist-calculation argument: without market prices for capital goods, rational economic planning is impossible, socialism fails not from bad motives but from missing information. Praxeology reconstructs economics as the deductive science of human action.", "g": "thinker-ludwig-von-mises", "k": "Ludwig von Mises", "c": "The Austrian School and the Classical-Liberal Revival", "e": "The Twentieth Century"}, {"n": "Friedrich Hayek", "d": "1899–1992", "w": "The Road to Serfdom; The Constitution of Liberty; Law, Legislation and Liberty; “The Use of Knowledge in Society”", "s": "Society’s knowledge is dispersed, tacit, and local, so central planning must fail and prices function as a discovery procedure; liberty and the rule of law are the conditions for using knowledge no single mind can hold. Law grown (nomos) differs from law made (thesis); “social justice” applied to spontaneous orders is a mirage; and comprehensive planning tends, institutionally, toward serfdom.", "g": "thinker-friedrich-hayek", "k": "Friedrich Hayek", "c": "The Austrian School and the Classical-Liberal Revival", "e": "The Twentieth Century"}, {"n": "Karl Popper", "d": "1902–1994", "w": "The Open Society and Its Enemies; The Poverty of Historicism", "s": "Falsificationism applied to politics: historicist prophecy (Plato, Hegel, Marx) is pseudo-science, and utopian engineering invites tyranny. Prefer piecemeal reform and, the key question, institutions that let citizens remove bad rulers without bloodshed.", "g": "thinker-karl-popper", "k": "Karl Popper", "c": "The Austrian School and the Classical-Liberal Revival", "e": "The Twentieth Century"}, {"n": "Milton Friedman", "d": "1912–2006", "w": "Capitalism and Freedom; Free to Choose", "s": "Competitive capitalism is a necessary condition of political freedom, dispersing power the state would otherwise concentrate. Supplied liberalism’s policy technology: school vouchers, the negative income tax, floating exchange rates, and the volunteer army.", "g": "thinker-milton-friedman", "k": "Milton Friedman", "c": "The Austrian School and the Classical-Liberal Revival", "e": "The Twentieth Century"}, {"n": "James M. Buchanan", "d": "1919–2013", "w": "The Calculus of Consent (with Gordon Tullock); The Limits of Liberty", "s": "Public choice: “politics without romance”, politicians, voters, and bureaucrats respond to incentives like everyone else, so market failure must be weighed against government failure. Constitutional political economy asks which rules citizens would unanimously choose behind uncertainty.", "g": "thinker-james-m-buchanan", "k": "James M. Buchanan", "c": "The Austrian School and the Classical-Liberal Revival", "e": "The Twentieth Century"}, {"n": "Ayn Rand", "d": "1905–1982", "w": "Atlas Shrugged; The Fountainhead; The Virtue of Selfishness", "s": "Objectivism: rational egoism as ethics, laissez-faire capitalism as the only social system consistent with man’s nature as a rational trader, and the producer as the mover of the world. Heterodox as philosophy, and of considerable cultural consequence.", "g": "thinker-ayn-rand", "k": "Ayn Rand", "c": "Libertarianism", "e": "The Twentieth Century"}, {"n": "Murray Rothbard", "d": "1926–1995", "w": "Man, Economy, and State; The Ethics of Liberty; For a New Liberty", "s": "Anarcho-capitalism deduced from self-ownership and homesteading: all state functions, courts and defense included, can be supplied by market and contract, and the state itself is “a gang of thieves writ large.”", "g": "thinker-murray-rothbard", "k": "Murray Rothbard", "c": "Libertarianism", "e": "The Twentieth Century"}, {"n": "Robert Nozick", "d": "1938–2002", "w": "Anarchy, State, and Utopia", "s": "Rights as side constraints; the entitlement theory of justice, just acquisition, just transfer, rectification, against patterned end-states; the Wilt Chamberlain argument that “liberty upsets patterns”; and the framework-for-utopias. Only the minimal state is justified: the great libertarian answer to Rawls, published three years after A Theory of Justice.", "g": "thinker-robert-nozick", "k": "Robert Nozick", "c": "Libertarianism", "e": "The Twentieth Century"}, {"n": "Isaiah Berlin", "d": "1909–1997", "w": "Two Concepts of Liberty; Four Essays on Liberty; The Hedgehog and the Fox", "s": "Negative liberty (freedom from interference) versus positive liberty (rational self-mastery), and the political perversion of the latter into “forcing men to be free.” Value pluralism: ultimate goods genuinely conflict, tragedy is ineliminable, and monism in politics breeds despotism.", "g": "thinker-isaiah-berlin", "k": "Isaiah Berlin", "c": "Egalitarian Liberalism and the Analytic Renaissance", "e": "The Twentieth Century"}, {"n": "John Rawls", "d": "1921–2002", "w": "A Theory of Justice; Political Liberalism; The Law of Peoples", "s": "Justice as fairness: behind a veil of ignorance, parties choose equal basic liberties and the difference principle, inequalities must work to the greatest benefit of the least advantaged. Later, political liberalism seeks an overlapping consensus among reasonable comprehensive doctrines. The book that single-handedly revived normative political philosophy.", "g": "thinker-john-rawls", "k": "John Rawls", "c": "Egalitarian Liberalism and the Analytic Renaissance", "e": "The Twentieth Century"}, {"n": "Ronald Dworkin", "d": "1931–2013", "w": "Taking Rights Seriously; Law’s Empire; Sovereign Virtue", "s": "Rights as trumps over collective goals; law as integrity, interpreted in its best moral light; and equality of resources, the envy test and hypothetical insurance market, aiming at distributions sensitive to ambition but insensitive to brute luck.", "g": "thinker-ronald-dworkin", "k": "Ronald Dworkin", "c": "Egalitarian Liberalism and the Analytic Renaissance", "e": "The Twentieth Century"}, {"n": "Alasdair MacIntyre", "d": "1929–2025", "w": "After Virtue; Whose Justice? Which Rationality?", "s": "Modern moral discourse is a heap of fragments from lost traditions: hence interminable disagreement and emotivism. The repair: Aristotelian virtue recovered within practices, the narrative unity of a life, and living traditions of inquiry.", "g": "thinker-alasdair-macintyre", "k": "Alasdair MacIntyre", "c": "Communitarianism", "e": "The Twentieth Century"}, {"n": "Michael Walzer", "d": "b. 1935", "w": "Spheres of Justice; Just and Unjust Wars", "s": "Complex equality: different goods (money, office, honor, love) have different distributive logics, and injustice is dominance, converting advantage in one sphere into advantage in another. Also the modern classic of just-war theory.", "g": "thinker-michael-walzer", "k": "Michael Walzer", "c": "Communitarianism", "e": "The Twentieth Century"}, {"n": "Charles Taylor", "d": "b. 1931", "w": "Sources of the Self; The Politics of Recognition; A Secular Age", "s": "Selves are dialogical, constituted by strong evaluations within webs of interlocution; misrecognition is therefore a real harm, grounding the politics of recognition and multicultural accommodation.", "g": "thinker-charles-taylor", "k": "Charles Taylor (philosopher)", "c": "Communitarianism", "e": "The Twentieth Century"}, {"n": "Michael Sandel", "d": "b. 1953", "w": "Liberalism and the Limits of Justice; What Money Can’t Buy; The Tyranny of Merit", "s": "Critique of the Rawlsian “unencumbered self” that owns its ends without being constituted by them; later, the moral limits of markets, some goods are corrupted by sale, and the hubris of meritocracy.", "g": "thinker-michael-sandel", "k": "Michael Sandel", "c": "Communitarianism", "e": "The Twentieth Century"}, {"n": "Antonio Gramsci", "d": "1891–1937", "w": "Prison Notebooks", "s": "Hegemony: ruling classes rule by consent manufactured in civil society, schools, churches, press, not by force alone. Hence the “war of position” in culture and the organic intellectual. Written in Mussolini’s prisons.", "g": "thinker-antonio-gramsci", "k": "Antonio Gramsci", "c": "Western Marxism and the Frankfurt School", "e": "The Twentieth Century"}, {"n": "György Lukács", "d": "1885–1971", "w": "History and Class Consciousness", "s": "Reification: under commodity production, social relations congeal into thing-like “second nature,” and consciousness itself is colonized, the founding text of Western Marxism.", "g": "thinker-gyorgy-lukacs", "k": "György Lukács", "c": "Western Marxism and the Frankfurt School", "e": "The Twentieth Century"}, {"n": "Max Horkheimer and Theodor W. Adorno", "d": "1895–1973; 1903–1969", "w": "Dialectic of Enlightenment; Adorno, Minima Moralia", "s": "Enlightenment reason, reduced to instrumental domination of nature and men, reverts to myth, Odysseus to Auschwitz; the culture industry administers consciousness and manufactures conformity as entertainment.", "g": "thinker-max-horkheimer-and-theodor-w-adorno", "k": "Max Horkheimer", "c": "Western Marxism and the Frankfurt School", "e": "The Twentieth Century"}, {"n": "Herbert Marcuse", "d": "1898–1979", "w": "One-Dimensional Man; Eros and Civilization", "s": "Advanced industrial society absorbs opposition through affluence, technology, and “repressive tolerance,” producing one-dimensional thought. The philosopher of the New Left.", "g": "thinker-herbert-marcuse", "k": "Herbert Marcuse", "c": "Western Marxism and the Frankfurt School", "e": "The Twentieth Century"}, {"n": "Jürgen Habermas", "d": "b. 1929", "w": "The Structural Transformation of the Public Sphere; The Theory of Communicative Action; Between Facts and Norms", "s": "Communicative reason against instrumental reason: norms are valid if all affected could accept them in uncoerced rational discourse. The bourgeois public sphere, its rise and refeudalization; deliberative democracy and the co-originality of private rights and popular sovereignty.", "g": "thinker-jurgen-habermas", "k": "Jürgen Habermas", "c": "Western Marxism and the Frankfurt School", "e": "The Twentieth Century"}, {"n": "Carl Schmitt", "d": "1888–1985", "w": "The Concept of the Political; Political Theology", "s": "The political is the friend–enemy distinction, irreducible to economics or ethics; “sovereign is he who decides on the exception.” A Nazi jurist and liberalism’s most dangerous critic, studied precisely because his diagnosis of liberal evasions still stings.", "g": "thinker-carl-schmitt", "k": "Carl Schmitt", "c": "Totalitarianism and Its Interpreters", "e": "The Twentieth Century"}, {"n": "Hannah Arendt", "d": "1906–1975", "w": "The Origins of Totalitarianism; The Human Condition; On Revolution; Eichmann in Jerusalem", "s": "Totalitarianism as a novel regime of terror plus ideology, made possible by loneliness and superfluousness; politics recovered as action and natality, beginning something new among plural equals; the “banality of evil”; and the lost treasure of the revolutionary council tradition.", "g": "thinker-hannah-arendt", "k": "Hannah Arendt", "c": "Totalitarianism and Its Interpreters", "e": "The Twentieth Century"}, {"n": "Leo Strauss", "d": "1899–1973", "w": "Natural Right and History; Persecution and the Art of Writing", "s": "Against historicism and relativism, the “German nihilism” he saw feeding catastrophe, a return to the quarrel between ancients and moderns and to classical natural right; philosophers under persecution write esoterically, between the lines.", "g": "thinker-leo-strauss", "k": "Leo Strauss", "c": "Totalitarianism and Its Interpreters", "e": "The Twentieth Century"}, {"n": "Michael Oakeshott", "d": "1901–1990", "w": "Rationalism in Politics; On Human Conduct", "s": "Conservative skepticism about “rationalism”: the delusion that technique can replace practical knowledge. Politics is “the pursuit of intimations” within a tradition; civil association (rules) must not be swallowed by enterprise association (collective purpose).", "g": "thinker-michael-oakeshott", "k": "Michael Oakeshott", "c": "Totalitarianism and Its Interpreters", "e": "The Twentieth Century"}, {"n": "Michel Foucault", "d": "1926–1984", "w": "Discipline and Punish; The History of Sexuality, Vol. 1; lectures on governmentality", "s": "Power is productive and capillary, working through discipline, surveillance, and normalization rather than only law and prohibition; knowledge and power are entangled (power/knowledge). Genealogies of the prison, the clinic, and sexuality; later, biopolitics and governmentality, the conduct of conduct.", "g": "thinker-michel-foucault", "k": "Michel Foucault", "c": "Post-structuralism and Postmodernism", "e": "The Twentieth Century"}, {"n": "Jacques Derrida", "d": "1930–2004", "w": "Of Grammatology; “Force of Law”", "s": "Deconstruction of the binary hierarchies structuring Western thought; law is deconstructible, but justice, always owed to the singular other, always “to come”, is not.", "g": "thinker-jacques-derrida", "k": "Jacques Derrida", "c": "Post-structuralism and Postmodernism", "e": "The Twentieth Century"}, {"n": "Jean-François Lyotard", "d": "1924–1998", "w": "The Postmodern Condition", "s": "The postmodern defined as “incredulity toward metanarratives”: the grand stories of emancipation and progress have lost their legitimating power, leaving a plurality of language games.", "g": "thinker-jean-francois-lyotard", "k": "Jean-François Lyotard", "c": "Post-structuralism and Postmodernism", "e": "The Twentieth Century"}, {"n": "Simone de Beauvoir", "d": "1908–1986", "w": "The Second Sex", "s": "“One is not born, but rather becomes, a woman”: woman is constructed as the Other against man as the default subject. The existentialist foundation of second-wave feminism.", "g": "thinker-simone-de-beauvoir", "k": "Simone de Beauvoir", "c": "Feminist Political Thought", "e": "The Twentieth Century"}, {"n": "Susan Moller Okin", "d": "1946–2004", "w": "Justice, Gender, and the Family", "s": "The family is the first school of justice: and mainstream theories from Rawls onward simply ignore it. Gender-structured marriage manufactures women’s vulnerability; a just society must apply its principles inside the household.", "g": "thinker-susan-moller-okin", "k": "Susan Moller Okin", "c": "Feminist Political Thought", "e": "The Twentieth Century"}, {"n": "Catharine MacKinnon", "d": "b. 1946", "w": "Toward a Feminist Theory of the State", "s": "Sexuality is the linchpin of gender inequality, and law’s ostensible neutrality encodes the male standpoint. Pioneered sexual-harassment law: theory that changed legal reality.", "g": "thinker-catharine-mackinnon", "k": "Catharine MacKinnon", "c": "Feminist Political Thought", "e": "The Twentieth Century"}, {"n": "Judith Butler", "d": "b. 1956", "w": "Gender Trouble", "s": "Gender is performative, constituted by iterated acts rather than expressing a prior essence, and the regulation of intelligible identity is itself a political operation.", "g": "thinker-judith-butler", "k": "Judith Butler", "c": "Feminist Political Thought", "e": "The Twentieth Century"}, {"n": "M. K. Gandhi", "d": "1869–1948", "w": "Hind Swaraj; An Autobiography (The Story of My Experiments with Truth)", "s": "Swaraj is self-rule of the self, not merely national independence: satyagraha, truth-force, disciplined nonviolent resistance, converts rather than coerces the opponent, joined to a radical critique of industrial civilization itself.", "g": "thinker-m-k-gandhi", "k": "Mahatma Gandhi", "c": "Anti-colonial and Postcolonial Thought", "e": "The Twentieth Century"}, {"n": "B. R. Ambedkar", "d": "1891–1956", "w": "Annihilation of Caste; States and Minorities", "s": "Caste is graded inequality that reform within Hinduism cannot cure: hence annihilation, not adjustment. Constitutional democracy must deliver “one person, one value” socially, not just politically; principal architect of India’s Constitution and the deepest theorist of social democracy in the Indian tradition.", "g": "thinker-b-r-ambedkar", "k": "B. R. Ambedkar", "c": "Anti-colonial and Postcolonial Thought", "e": "The Twentieth Century"}, {"n": "Frantz Fanon", "d": "1925–1961", "w": "The Wretched of the Earth; Black Skin, White Masks", "s": "Colonialism is total violence inscribed on economy and psyche alike; decolonization remakes both, and national consciousness has pitfalls, the native bourgeoisie replacing the settler. The clinical and political classic of decolonization.", "g": "thinker-frantz-fanon", "k": "Frantz Fanon", "c": "Anti-colonial and Postcolonial Thought", "e": "The Twentieth Century"}, {"n": "Edward Said", "d": "1935–2003", "w": "Orientalism", "s": "“The Orient” is a Western discursive construction: a style of thought and rule that produced the East it claimed merely to describe. The founding text of postcolonial studies.", "g": "thinker-edward-said", "k": "Edward Said", "c": "Anti-colonial and Postcolonial Thought", "e": "The Twentieth Century"}, {"n": "Amartya Sen", "d": "b. 1933", "w": "Development as Freedom; The Idea of Justice; Collective Choice and Social Welfare", "s": "Evaluate arrangements by capabilities, substantive freedoms, rather than resources or utility alone; famines are failures of entitlements, not of food supply, and do not occur in functioning democracies with a free press. Justice should proceed comparatively (removing manifest injustices) rather than by designing transcendentally perfect institutions.", "g": "thinker-amartya-sen", "k": "Amartya Sen", "c": "The Capability Approach", "e": "Contemporary Political Philosophy"}, {"n": "Martha Nussbaum", "d": "b. 1947", "w": "Frontiers of Justice; Creating Capabilities; Women and Human Development", "s": "Specifies ten central capabilities, life, bodily integrity, practical reason, affiliation, and more, as constitutional minimums every government must secure, extending justice to disability, nationality, and non-human animals where contract theory stalls.", "g": "thinker-martha-nussbaum", "k": "Martha Nussbaum", "c": "The Capability Approach", "e": "Contemporary Political Philosophy"}, {"n": "G. A. Cohen", "d": "1941–2009", "w": "Karl Marx’s Theory of History: A Defence; Rescuing Justice and Equality; Why Not Socialism?", "s": "Rebuilt historical materialism with analytic rigor (functional explanation, no dialectical hand-waving); later argued that Rawls concedes too much, incentive-based inequalities fail justice, which requires an egalitarian ethos in daily choices, not just in institutions.", "g": "thinker-g-a-cohen", "k": "G. A. Cohen", "c": "Analytical Marxism and Left Egalitarianism", "e": "Contemporary Political Philosophy"}, {"n": "Quentin Skinner", "d": "b. 1940", "w": "Liberty before Liberalism; The Foundations of Modern Political Thought", "s": "Cambridge-school contextualism, texts answer the questions of their moment, and the recovery of the neo-Roman insight that dependence on another’s will is itself unfreedom, even if the master never strikes.", "g": "thinker-quentin-skinner", "k": "Quentin Skinner", "c": "Neo-Republicanism", "e": "Contemporary Political Philosophy"}, {"n": "Philip Pettit", "d": "b. 1945", "w": "Republicanism: A Theory of Freedom and Government; On the People’s Terms", "s": "Freedom as non-domination: security against arbitrary power, achieved through the rule of law, dispersed authority, and contestatory democracy, institutions citizens can challenge and force to track their avowable interests.", "g": "thinker-philip-pettit", "k": "Philip Pettit", "c": "Neo-Republicanism", "e": "Contemporary Political Philosophy"}, {"n": "T. M. Scanlon", "d": "b. 1940", "w": "What We Owe to Each Other", "s": "Contractualism: an act is wrong if it would be disallowed by principles that no one could reasonably reject, morality as a system of mutual justifiability among equals.", "g": "thinker-t-m-scanlon", "k": "T. M. Scanlon", "c": "Public Reason, Contractualism, and Perfectionism", "e": "Contemporary Political Philosophy"}, {"n": "Joseph Raz", "d": "1939–2022", "w": "The Morality of Freedom", "s": "Perfectionist liberalism: autonomy is valuable only amid an adequate range of genuinely good options, so the state may act to sustain them; authority is legitimate when following it helps subjects better conform to reason (the service conception).", "g": "thinker-joseph-raz", "k": "Joseph Raz", "c": "Public Reason, Contractualism, and Perfectionism", "e": "Contemporary Political Philosophy"}, {"n": "Jeremy Waldron", "d": "b. 1953", "w": "Law and Disagreement; The Dignity of Legislation", "s": "Takes disagreement seriously as the circumstance of politics: legislatures, where equals decide by majority, deserve pride of place, grounding a principled skepticism about judicial review of rights.", "g": "thinker-jeremy-waldron", "k": "Jeremy Waldron", "c": "Public Reason, Contractualism, and Perfectionism", "e": "Contemporary Political Philosophy"}, {"n": "Peter Singer", "d": "b. 1946", "w": "“Famine, Affluence, and Morality”; Practical Ethics; Animal Liberation", "s": "Impartial utilitarianism: if we can prevent something bad without sacrificing anything of comparable moral importance, we ought to do it, affluence therefore entails stringent duties to the global poor; species membership is morally irrelevant. The fountainhead of effective altruism.", "g": "thinker-peter-singer", "k": "Peter Singer", "c": "Global Justice", "e": "Contemporary Political Philosophy"}, {"n": "Thomas Pogge", "d": "b. 1953", "w": "World Poverty and Human Rights", "s": "The global institutional order, borrowing and resource privileges, trade rules, actively harms the poor, so even mere negative duties not to harm suffice to ground demanding reforms.", "g": "thinker-thomas-pogge", "k": "Thomas Pogge", "c": "Global Justice", "e": "Contemporary Political Philosophy"}, {"n": "Will Kymlicka", "d": "b. 1962", "w": "Multicultural Citizenship", "s": "A liberal defense of group-differentiated rights: societal cultures are contexts of choice that make autonomy possible, so minority cultural protections can serve, not betray, liberal values.", "g": "thinker-will-kymlicka", "k": "Will Kymlicka", "c": "Multiculturalism, Recognition, and Difference", "e": "Contemporary Political Philosophy"}, {"n": "Axel Honneth", "d": "b. 1949", "w": "The Struggle for Recognition; Freedom’s Right", "s": "Justice as adequate recognition across three spheres, love, rights, and social esteem; social conflicts are at bottom struggles for recognition, updating Hegel for critical theory.", "g": "thinker-axel-honneth", "k": "Axel Honneth", "c": "Multiculturalism, Recognition, and Difference", "e": "Contemporary Political Philosophy"}, {"n": "Nancy Fraser", "d": "b. 1947", "w": "Justice Interruptus; Redistribution or Recognition? (with Honneth)", "s": "Justice has three irreducible dimensions, redistribution, recognition, and representation, with participatory parity as the common standard; neither class politics nor identity politics alone suffices.", "g": "thinker-nancy-fraser", "k": "Nancy Fraser", "c": "Multiculturalism, Recognition, and Difference", "e": "Contemporary Political Philosophy"}, {"n": "Iris Marion Young", "d": "1949–2006", "w": "Justice and the Politics of Difference", "s": "Against the distributive paradigm’s blindness to structure: oppression has five faces, exploitation, marginalization, powerlessness, cultural imperialism, and violence, and justice requires attending to group difference, not abstracting from it.", "g": "thinker-iris-marion-young", "k": "Iris Marion Young", "c": "Multiculturalism, Recognition, and Difference", "e": "Contemporary Political Philosophy"}, {"n": "Charles W. Mills", "d": "1951–2021", "w": "The Racial Contract", "s": "The social contract was, historically, a racial contract among whites, with white supremacy as an unnamed political system; ideal theory functions as ideology, and philosophy must start from actual, non-ideal injustice.", "g": "thinker-charles-w-mills", "k": "Charles W. Mills", "c": "Multiculturalism, Recognition, and Difference", "e": "Contemporary Political Philosophy"}, {"n": "Ernesto Laclau and Chantal Mouffe", "d": "1935–2014; b. 1943", "w": "Hegemony and Socialist Strategy; Mouffe, The Democratic Paradox; On the Political", "s": "Post-Marxist discourse theory: no social identity or “objective interest” precedes political articulation; hegemony is the contingent linking of demands. Politics is constitutively antagonistic: the democratic aim is agonism, adversaries rather than enemies, against the consensus fantasies of third-way liberalism.", "g": "thinker-ernesto-laclau-and-chantal-mouffe", "k": "Chantal Mouffe", "c": "Agonistic and Radical Democracy", "e": "Contemporary Political Philosophy"}, {"n": "Elinor Ostrom", "d": "1933–2012", "w": "Governing the Commons", "s": "Neither privatization nor Leviathan is necessary: communities craft polycentric rules, eight design principles, from monitoring to graduated sanctions, that sustain common-pool resources for centuries. Nobel laureate in economics (2009), and empirical vindication of self-governance.", "g": "thinker-elinor-ostrom", "k": "Elinor Ostrom", "c": "Institutions and the Commons", "e": "Contemporary Political Philosophy"}, {"n": "Francis Fukuyama", "d": "b. 1952", "w": "The End of History and the Last Man; The Origins of Political Order; Political Order and Political Decay", "s": "Liberal democracy as the endpoint of ideological evolution, with the lingering problem of thymos, the desire for recognition; the later volumes soberly reconstruct how state, rule of law, and accountability arise, and how institutions decay through capture.", "g": "thinker-francis-fukuyama", "k": "Francis Fukuyama", "c": "History’s Direction, Revisited", "e": "Contemporary Political Philosophy"}, {"n": "Samuel Huntington", "d": "1927–2008", "w": "The Clash of Civilizations; Political Order in Changing Societies", "s": "Post-Cold War conflict runs along civilizational fault lines, not ideological ones; earlier and more enduringly, the gap between social mobilization and institutional development, not poverty itself, explains political instability.", "g": "thinker-samuel-huntington", "k": "Samuel P. Huntington", "c": "History’s Direction, Revisited", "e": "Contemporary Political Philosophy"}, {"n": "Giorgio Agamben", "d": "b. 1942", "w": "Homo Sacer; State of Exception", "s": "Sovereign power produces “bare life”, life stripped of political standing, and the state of exception has become the working paradigm of modern government; the camp, not the city, is modernity’s hidden nomos.", "g": "thinker-giorgio-agamben", "k": "Giorgio Agamben", "c": "Radical Continental Thought", "e": "Contemporary Political Philosophy"}, {"n": "Slavoj Žižek", "d": "b. 1949", "w": "The Sublime Object of Ideology", "s": "Lacan crossed with Hegel and Marx: ideology today operates through disavowed practice, “they know very well what they are doing, but still, they are doing it”, structuring desire even among the cynical.", "g": "thinker-slavoj-zizek", "k": "Slavoj Žižek", "c": "Radical Continental Thought", "e": "Contemporary Political Philosophy"}, {"n": "Alain Badiou", "d": "b. 1937", "w": "Being and Event", "s": "Politics as one of four truth procedures inaugurated by an event, a rupture the existing situation cannot count, and sustained by militant fidelity against the state of things.", "g": "thinker-alain-badiou", "k": "Alain Badiou", "c": "Radical Continental Thought", "e": "Contemporary Political Philosophy"}];
